 fn query_escape(value: &str) -> String {
     value.bytes().fold(String::new(), |mut out, byte| {
         if byte.is_ascii_alphanumeric() || matches!(byte, b'-' | b'_' | b'.' | b'~') {
             out.push(char::from(byte));
         } else {
             use fmt::Write;
             let _ = write!(out, "%{byte:02X}");
         }
         out
     })
 }

