-        ensure!(!self.subject.is_empty() && self.subject.len() <= 1024 && !self.subject.chars().any(char::is_control), "Invalid account subject.");
-        ensure!(self.token_identifier == format!("{}|{}", self.issuer, self.subject), "The account identifier does not match its issuer and subject.");
+        ensure!(
