-        ensure!(!self.refresh_error && !self.issued_user_id.is_empty() && !self.session_id.is_empty() && self.issued_user_id == self.refreshed_user_id && self.issued_user_id == self.session_user_id, "Twyne could not confirm your session. Please sign in again.");
-        let identity = AccountIdentity { issuer: trusted_issuer.to_owned(), subject: self.issued_user_id.clone(), token_identifier: format!("{trusted_issuer}|{}", self.issued_user_id) };
+        ensure!(
